  (v_project_id, '3c3b469c-7c83-52c3-be35-8ce7edc8e2ba', 'a2ed19c7-0745-557e-a8a8-eb4b056e3860', 'isChildOf', 'asserted', NULL, 'accepted'),
  (v_project_id, 'b11b7046-88fe-5a24-a84b-9436308ac146', '88fea1a5-7454-5544-9059-ca7d999323ba', 'isChildOf', 'asserted', NULL, 'accepted'),
  (v_project_id, '78ffc8cd-bbc2-5257-b594-313cc0b1e540', '88fea1a5-7454-5544-9059-ca7d999323ba', 'isChildOf', 'asserted', NULL, 'accepted'),
  (v_project_id, '2a7661e3-93da-5c11-8689-db05832b4479', '5574d5cd-fcb7-5a9b-be14-1e40a5c7577a', 'isChildOf', 'asserted', NULL, 'accepted'),
  (v_project_id, '40ad77e0-2d04-5774-bb96-651b739405d0', '5574d5cd-fcb7-5a9b-be14-1e40a5c7577a', 'isChildOf', 'asserted', NULL, 'accepted'),
  (v_project_id, '476cea09-c8cc-54f4-885b-11fac51a2b89', 'b8e2f8ce-4b8b-533c-bb11-f850f502a133', 'isChildOf', 'asserted', NULL, 'accepted'),
  (v_project_id, '8428b51d-651b-5df1-a4a4-6dd0c33fc8ee', 'b8e2f8ce-4b8b-533c-bb11-f850f502a133', 'isChildOf', 'asserted', NULL, 'accepted'),
  (v_project_id, '7662dfdd-f8c4-54fb-8a64-c8cac92a2dea', 'e3a3b4cb-e41d-57cc-8e1a-7a21680c28d8', 'isChildOf', 'asserted', NULL, 'accepted'),
  (v_project_id, '7376ecd0-c8bd-520e-b1a0-c3c156370370', 'e3a3b4cb-e41d-57cc-8e1a-7a21680c28d8', 'isChildOf', 'asserted', NULL, 'accepted'),
  (v_project_id, '37729f9b-cb23-524a-9858-40b52ab9bbd2', '0178ab79-0e13-520e-b250-1cd9db82a922', 'relates_to', 'suggested', $J$compare selection in different environments.$J$, 'proposed'),
  (v_project_id, '37729f9b-cb23-524a-9858-40b52ab9bbd2', '8c5d9057-cd3b-5fb6-b9f3-a737a22d225c', 'relates_to', 'suggested', $J$add resource competition.$J$, 'proposed'),
  (v_project_id, '0178ab79-0e13-520e-b250-1cd9db82a922', '5574d5cd-fcb7-5a9b-be14-1e40a5c7577a', 'relates_to', 'suggested', $J$both invoke multilevel/kin selection explicitly; compare a spatial-isolation mechanism to a direct-monitoring/punishment mechanism as two different routes to the same cooperation-can-spread outcome.$J$, 'proposed'),
  (v_project_id, '0178ab79-0e13-520e-b250-1cd9db82a922', '8c5d9057-cd3b-5fb6-b9f3-a737a22d225c', 'relates_to', 'suggested', $J$same sustainable-vs-greedy harvest-type trait, without the spatial-isolation structure.$J$, 'proposed'),
  (v_project_id, '0178ab79-0e13-520e-b250-1cd9db82a922', 'a2ed19c7-0745-557e-a8a8-eb4b056e3860', 'relates_to', 'suggested', $J$same sustainable-vs-greedy harvest-type trait, without the spatial-isolation structure.$J$, 'proposed'),
  (v_project_id, '0178ab79-0e13-520e-b250-1cd9db82a922', 'e3a3b4cb-e41d-57cc-8e1a-7a21680c28d8', 'relates_to', 'suggested', $J$a third route to positive assortment (per evolution-ethnocentrism's own strand text), via ethnic-marker-based assortment rather than spatial isolation.$J$, 'proposed'),
  (v_project_id, '8c5d9057-cd3b-5fb6-b9f3-a737a22d225c', 'a2ed19c7-0745-557e-a8a8-eb4b056e3860', 'relates_to', 'suggested', $J$the same modest/greedy competition mechanic, generalized away from the forestry framing.$J$, 'proposed'),
  (v_project_id, '8c5d9057-cd3b-5fb6-b9f3-a737a22d225c', '88fea1a5-7454-5544-9059-ca7d999323ba', 'relates_to', 'suggested', $J$replaces the binary modest/greedy trait with a continuous harvest-rate trait and adds diminishing-returns harvesting costs.$J$, 'proposed'),
  (v_project_id, '8c5d9057-cd3b-5fb6-b9f3-a737a22d225c', '5574d5cd-fcb7-5a9b-be14-1e40a5c7577a', 'relates_to', 'suggested', $J$adds monitoring and punishment to essentially the same commons dilemma; the strongest direct A/B comparison in this set.$J$, 'proposed'),
  (v_project_id, 'a2ed19c7-0745-557e-a8a8-eb4b056e3860', '88fea1a5-7454-5544-9059-ca7d999323ba', 'relates_to', 'suggested', $J$replaces the binary trait with a continuous harvest-amount trait and adds harvesting-cost diminishing returns.$J$, 'proposed'),
  (v_project_id, '88fea1a5-7454-5544-9059-ca7d999323ba', 'b8e2f8ce-4b8b-533c-bb11-f850f502a133', 'relates_to', 'suggested', $J$adds social learning (imitation) on top of a similar harvest-trait-evolution mechanism, letting harvest behavior change within a lifetime, not only across generations.$J$, 'proposed'),
  (v_project_id, '5574d5cd-fcb7-5a9b-be14-1e40a5c7577a', 'e3a3b4cb-e41d-57cc-8e1a-7a21680c28d8', 'relates_to', 'suggested', $J$also invokes kin selection and frequency-dependent selection explicitly, via a different mechanism (ethnic-marker-based assortment rather than resource-monitoring).$J$, 'proposed'),
  (v_project_id, '5574d5cd-fcb7-5a9b-be14-1e40a5c7577a', 'b8e2f8ce-4b8b-533c-bb11-f850f502a133', 'relates_to', 'suggested', $J$a different social mechanism (monitoring/punishment) layered on the same base trait; useful contrast between cultural transmission and direct sanctioning as two distinct routes to norm stabilization.$J$, 'proposed'),
  (v_project_id, 'b8e2f8ce-4b8b-533c-bb11-f850f502a133', 'e3a3b4cb-e41d-57cc-8e1a-7a21680c28d8', 'relates_to', 'suggested', $J$adds the cultural-transmission mechanism this model explicitly lacks.$J$, 'proposed');
