-- netlogo-lpm-strands: 8 real NetLogo-model-anchored LPM strand drafts (the 2026-08-29
-- pass in netlogo/lpm-strands/*.md) migrated into their own private OpenLPM Project Space,
-- per Dustin's 2026-10-01 direction that OpenLPM -- not ConceptBase, not the netlogo repo --
-- is now where LPM content lives and where subject-matter-expert review happens. Pattern
-- follows 053_eva_lpm_seed.sql: deterministic UUIDs (generated by
-- scripts/generate_netlogo_lpm_strands_seed.py, not hand-typed), is_private = TRUE,
-- epistemic_status = 'in-development', maturity = 'draft', a real epistemic_status_note
-- stating plainly that zero human subject-matter-expert review has happened yet.
--
-- A first-pass quality review (2026-10-01, not expert review) spot-checked ConceptBase
-- competency IDs, 3 DOI citations against Crossref, and NetLogo model interface parameter
-- names -- all checked out as real, not fabricated. Two caveats from that review are carried
-- forward explicitly below (project epistemic_status_note and bug-evolution's own content),
-- not silently dropped: bug-evolution's theoretical grounding cites author-draft TheoryBase/
-- QuestionBase records, and cites 3 provisional (12-month-TTL, expiring 2027-08-06)
-- OE-SANDBOX-CONCEPT ids without flagging their provisional status in its own text.
--
-- Scope: 8 of the netlogo repo's 15 models (the 2026-08-29 'evolution-themed' pass). The
-- other 6 in-progress/complete strands (two-foresters, two-communities,
-- population-size-living-costs, beesmart-hive-finding) and the 3 not-started stubs
-- (swarming, virus-epidemic, wolves-sheep-grass) are not part of this migration.

DO $MIGRATION$
DECLARE
  v_project_id UUID := 'd1069507-098b-5806-b12b-73ed18c30f2a';
  v_user_id UUID;
BEGIN

  -- ------------------------------------------------------------------------
  -- Project Space
  -- ------------------------------------------------------------------------
  VALUES (
    v_project_id, $J$netlogo-lpm-strands$J$, $J$NetLogo LPM Strands$J$,
    $J$Learning Progression Map strands for 8 of the evolution-themed agent-based models in the sibling netlogo repo's teaching collection (the 2026-08-29 pass -- bug-evolution, island-world, evolution-competition-forest-resources, evolution-competition-resources-abstract, evolution-resource-use-harvest-efficiency, evolution-resource-use-social-behavior, evolution-resource-use-behavior-imitation, evolution-ethnocentrism). Each strand follows the 5-step process in netlogo/lpm-strands/README.md: grade-band progression, content-anchor/thinking-tool alignment, international curriculum grounding (real US NGSS codes and Sachsen Gymnasium Biologie Lernziele from EvoMentor's FWU MEM dataset), ConceptBase competency alignment, and an integrated-causal-reasoning assessment (existing item banks for 3 of the 8; vignette sketches, not yet built item banks, for the other 5). Step 5 of that process -- a formal, schema-validated contribution back to ConceptBase -- is what this project space is itself meant to make possible: real structured strand/grade-band objects, tagged against OpenEvo's content-anchor and thinking-tool vocabulary and cross-linked where the strands' own text draws real comparisons between models, rather than 8 free-standing prose files. Spot-checked 2026-10-01 (ConceptBase competency IDs, 3 DOI citations verified against Crossref, NetLogo model interface parameter names) -- all checked out as real, not fabricated. This is a first-pass quality review, not a substitute for human subject-matter-expert review, which has not yet happened for any of the 8 strands.$J$,
    'active', 'in-development',
    $J$Synthesized by an LLM across ConceptBase, each model's own metadata.json/model-card data, and (for international grounding) EvoMentor's real FWU MEM Sachsen dataset -- not validated by expert review or empirical classroom testing for any of the 8 strands. Spot-checked 2026-10-01 (ConceptBase competency IDs, 3 DOI citations verified against Crossref, NetLogo model interface parameter names) -- all checked out as real, not fabricated. This is a first-pass quality review, not a substitute for human subject-matter-expert review, which has not yet happened for any of the 8 strands. Two specific caveats carried forward from that review, not silently dropped: (1) bug-evolution's theoretical-rationale section cites TheoryBase/QuestionBase records (proposition:restructuration-grounds-icr-transfer and two question: records) that are themselves tagged review_status: author-draft (unreviewed) -- its theoretical backbone rests on other unreviewed content, not an independently validated theory. (2) bug-evolution also cites OE-SANDBOX-CONCEPT-000007/8/9 (Restructuration, Decentralized Causal Reasoning, Agent-Based Modeling) without flagging in the strand's own text that these are provisional sandbox concepts with a 12-month TTL, expiring 2027-08-06 -- flagged here since the source text doesn't carry the caveat itself. Both caveats are also recorded directly on bug-evolution's own lpm_data_objects row (content.caveats) for anyone querying that object alone.$J$,
    'hosted', TRUE, 'draft', NULL, 'general', '{}'::TEXT[],
    ARRAY['evolution','natural-selection','agent-based-modeling','netlogo','commons-dilemma','cooperation','cultural-evolution']::TEXT[],
    ARRAY['en']::TEXT[]
  )
  ON CONFLICT (slug) DO NOTHING;

  -- ------------------------------------------------------------------------
  -- Base link: competency alignment throughout cites real ConceptBase concept ids
  -- ------------------------------------------------------------------------
  VALUES (v_project_id, 'conceptbase', TRUE, FALSE)
  ON CONFLICT (project_id, base_repo) DO NOTHING;

  -- ------------------------------------------------------------------------
  -- Source declarations: one per strand markdown file, all structurally
  -- imported below (not merely declared-but-unimported).
  -- ------------------------------------------------------------------------

  -- ------------------------------------------------------------------------
  -- Schema elements: OpenEvo's real, canonical content-anchor (9) and
  -- thinking-tool (6) vocabulary, shared across all 8 strands below.
  -- ------------------------------------------------------------------------

  -- ------------------------------------------------------------------------
  -- Data objects: 8 strands + their grade-band sections (performance_indicator)
  -- ------------------------------------------------------------------------

  -- ------------------------------------------------------------------------
  -- Connections: grade-band -> strand (isChildOf, structural fact, asserted/
  -- accepted) and real cross-model comparisons drawn directly from the
  -- strands' own 'Connections to Other Models' text (relates_to, suggested/
  -- proposed -- the strand authors' own unreviewed pedagogical suggestions,
  -- not a verified curriculum sequence).
  -- ------------------------------------------------------------------------

  -- ------------------------------------------------------------------------
  -- Object tags: each strand -> the content anchors (primary/secondary) and
  -- thinking tools its own Content Anchor Alignment / Thinking Tool
  -- Integration sections name.
  -- ------------------------------------------------------------------------

  -- ------------------------------------------------------------------------
  -- Ownership: folded in directly (per 056_openevo_lpm_seed.sql's precedent,
  -- after 053_eva_lpm_seed.sql shipped without this and needed a same-day
  -- follow-up fix in 055 -- is_private = TRUE + no owner leaves a project
  -- invisible to everyone, including its own author).
  -- ------------------------------------------------------------------------
  SELECT id INTO v_user_id FROM users WHERE email = 'dustin.eirdosh@eva.mpg.de';

  IF v_user_id IS NULL THEN
    RAISE NOTICE 'No users row found for dustin.eirdosh@eva.mpg.de -- netlogo-lpm-strands was seeded without an owner. Add one manually (project_members + projects.created_by) once that account exists.';
  ELSE
    VALUES (v_project_id, v_user_id, 'owner')
    ON CONFLICT (project_id, user_id) DO UPDATE SET role = 'owner';

    UPDATE projects SET created_by = v_user_id
    WHERE id = v_project_id AND created_by IS NULL;
  END IF;

END $MIGRATION$;
